<?php

namespace Biigle\Modules\Ptp;

use Biigle\Modules\Laserpoints\Volume;
use Illuminate\Database\Eloquent\Model;
use Biigle\ImageAnnotation;

/**
 * Each point-to-polygon conversion for a volume is represented as a PTP job.
 * The possible polygons generated by SAM are stored as annotations, connecting
 * this PtpJob Model to the PtpAnnotation Model.
 */
class PtpJob extends Model {


    /**
     * These attributes can be mass assigned when creating a PTP job.
     *
     * @var string[]
     */
    protected $fillable = [
        "volume_id",
        "status",
        "conversion_options"
    ];

    /**
     * All submitted options in the ptp job form are saved and casted to an array.
     *
     * @var string[]
     */
    protected $casts = [
        "conversion_options" => "array"
    ];


    /**
     * The volume this PTP job belongs to.
     *
     * @return \Illuminate\Database\Eloquent\Relations\BelongsTo
     */
    public function volume() {

        return $this->belongsTo(Volume::class);
    }


    /**
     * Gets the possible polygon annotations for this PTP job.
     * Each polygon annotation has a reference to this job through its ptp_job_id.
     *
     * @return \Illuminate\Database\Eloquent\Relations\HasMany
     */
    public function annotations() {

        return $this->hasMany(PtpAnnotation::class, "ptp_job_id");
    }


}
